with enriched as (select id, store_name, city, region, sqft, avg(sqft) over w_hist as running_avg_sqft, count(sqft) over w_hist as running_count_sqft, sum(sqft) over w_hist as running_sum_sqft from stores window w_hist as (partition by city, region order by sqft, id rows between unbounded preceding and current row)) select case when sqft >= 17293 then 'PREMIUM' else 'STANDARD' end as sqft_tier, count_if(region = 'South') as south_events, round(avg(sqft), 2) as avg_sqft, count(*) filter (where region = 'Central') as central_rows, max(running_sum_sqft) filter (where region = 'East') as east_max_running_sum_sqft from enriched group by case when sqft >= 17293 then 'PREMIUM' else 'STANDARD' end order by sqft_tier;
